add_expense:
def add_expense (s : State) (a : Int) (c : String) : Except String (Nat × State) :=
  if a ≤ 0 then .error "amount must be positive"
  else if c = "" then .error "category must not be empty"
  else .ok (s.expenses.length + 1, { s with expenses := s.expenses ++ [⟨a, c, none⟩] })

over_budget:
def over_budget (s : State) : List String :=
  sort_names ((s.budgets.filter (fun p : String × Int =>
    decide (budget_of s.budgets p.1 < cat_spend (by_category s) p.1))).map (fun p : String × Int => p.1))

set_budget:
def set_budget (s : State) (c : String) (a : Int) : Except String (Int × State) :=
  if a < 0 then .error "budget must not be negative"
  else .ok (a, { s with budgets := budget_set s.budgets c a })
